import React,{useState} from 'react';
import type {Stop,Appointment} from './domain';
import {deliveryWindow,isWithinDeliveryWindow,requiresReason} from './domain';
import {moveUp} from './logic';

type Proposal={title:string;fileId:string};
type Props={storeId:string;proposal?:Proposal;onSubmit:(data:unknown)=>void;stops?:Stop[];onMove?:(move:{id:string;position:number})=>void;notice?:{sentAt:number};appointments?:Appointment[];now?:number;onSchedule?:(at:number)=>void;onStopChange?:(stop:Stop,reason:string)=>void};
export function PlanningScreen(props:Props){return <ProposalForm key={props.storeId} {...props}/>;}
function ProposalForm({storeId,proposal,onSubmit,stops=[],onMove,notice,appointments=[],now=Date.now(),onSchedule,onStopChange}:Props){
  const [form,setForm]=useState<Proposal>({title:'',fileId:''});
  const [schedule,setSchedule]=useState('');
  const [reasonFor,setReasonFor]=useState<Stop>();
  const [reason,setReason]=useState('');
  const window=notice?deliveryWindow(notice,appointments,now):undefined;
  const scheduledAt=schedule?new Date(schedule).getTime():NaN;
  const scheduleValid=Boolean(window&&Number.isFinite(scheduledAt)&&isWithinDeliveryWindow(scheduledAt,window));
  return <main>
    <form onSubmit={e=>{e.preventDefault();onSubmit({storeId,...form});}}>
      <label>Title<input aria-label="Title" value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label>
      <button type="button" onClick={()=>proposal&&setForm({...proposal})} disabled={!proposal}>Use upload</button>
      <button type="submit">Save</button>
    </form>
    {stops.length>0&&<section aria-label="Delivery stops"><h2>Stops</h2><ol>{stops.filter(stop=>!stop.removed).map((stop,index)=><li key={stop.id}>
      {stop.id} {stop.status}
      <button type="button" aria-label={`Move ${stop.id} up`} disabled={index===0} onClick={()=>{const move=moveUp(stops,index);if(move)onMove?.(move);}}>Move up</button>
      {requiresReason(stop)&&<button type="button" onClick={()=>{setReasonFor(stop);setReason('');}}>Change stop</button>}
    </li>)}</ol></section>}
    {reasonFor&&<section role="dialog" aria-label="Change reason"><label>Reason<input aria-label="Reason" value={reason} onChange={e=>setReason(e.target.value)}/></label><button type="button" disabled={!reason.trim()} onClick={()=>{onStopChange?.(reasonFor,reason.trim());setReasonFor(undefined);}}>Submit change</button><button type="button" onClick={()=>setReasonFor(undefined)}>Cancel</button></section>}
    {notice&&<section aria-label="Schedule delivery"><label>Delivery time<input aria-label="Delivery time" type="datetime-local" value={schedule} min={window?new Date(window.from).toISOString().slice(0,16):undefined} max={window?new Date(window.to).toISOString().slice(0,16):undefined} onChange={e=>setSchedule(e.target.value)}/></label><button type="button" disabled={!scheduleValid} onClick={()=>onSchedule?.(scheduledAt)}>Schedule</button></section>}
  </main>;
}

