export type Stop={id:string;position:number;removed?:boolean;startedOn?:string;status:'NEW'|'IN_PROGRESS'|'POSTPONED'|'DONE'};
export const isStarted=(stop:Stop)=>Boolean(stop.startedOn)||stop.status==='IN_PROGRESS'||stop.status==='POSTPONED'||stop.status==='DONE';
export const isFinished=(stop:Stop)=>stop.status==='DONE';
export const requiresReason=(stop:Stop)=>isStarted(stop)&&!isFinished(stop);

export type Appointment={at:number;status:string};
export function deliveryWindow(notice:{sentAt:number},appointments:Appointment[],now:number){
  const next=appointments.filter(a=>a.status!=='CANCELLED'&&a.status!=='HELD'&&a.at>now).sort((a,b)=>a.at-b.at)[0];
  return next?{from:notice.sentAt,to:next.at}:undefined;
}
export function isWithinDeliveryWindow(at:number,window:{from:number;to:number}){return at>=window.from&&at<=window.to;}

