import {deliveryWindow,isWithinDeliveryWindow,requiresReason,type Appointment,type Stop} from './domain';

// activeIndex is the zero based rank in the visible (non-removed) stop list.
// The API expects a 1 based rank, so moving one row up means rank activeIndex.
export function moveUp(stops:Stop[],activeIndex:number){
  const active=stops.filter(stop=>!stop.removed);
  if(activeIndex<=0||activeIndex>=active.length) return undefined;
  return {id:active[activeIndex].id,position:activeIndex};
}
export const screenRequiresReason=requiresReason;
export function fitsWindow(at:number,notice:{sentAt:number},appointments:Appointment[],now:number){
  const window=deliveryWindow(notice,appointments,now);
  return Boolean(window&&isWithinDeliveryWindow(at,window));
}

