import {test,expect} from 'bun:test';
import {deliveryWindow,requiresReason} from './domain';
import {fitsWindow,moveUp,screenRequiresReason} from './logic';
import type {Stop} from './domain';

test('scheduling accepts both window bounds and rejects just outside each',()=>{
  const notice={sentAt:10},appointments=[{at:30,status:'PLANNED'}];
  expect(fitsWindow(10,notice,appointments,5)).toBe(true);
  expect(fitsWindow(30,notice,appointments,5)).toBe(true);
  expect(fitsWindow(9,notice,appointments,5)).toBe(false);
  expect(fitsWindow(31,notice,appointments,5)).toBe(false);
});

test('window ends at the next relevant appointment, ignoring cancelled and held entries',()=>{
  expect(deliveryWindow({sentAt:10},[
    {at:15,status:'CANCELLED'},{at:16,status:'HELD'},{at:20,status:'PLANNED'},{at:25,status:'PLANNED'},
  ],10)).toEqual({from:10,to:20});
});

test('move sends active rank even when retained history left stored position gaps',()=>{
  const stops:Stop[]=[
    {id:'a',position:1,status:'NEW'},
    {id:'removed',position:2,status:'NEW',removed:true},
    {id:'b',position:3,status:'NEW'},
    {id:'c',position:4,status:'NEW'},
  ];
  expect(moveUp(stops,2)).toEqual({id:'c',position:2});
});

test('screen and server share started unfinished reason rule',()=>{
  const cases:Stop[]=[
    {id:'new',position:1,status:'NEW'},
    {id:'started',position:2,status:'IN_PROGRESS',startedOn:'2026-01-01'},
    {id:'postponed',position:3,status:'POSTPONED',startedOn:'2026-01-01'},
    {id:'finished',position:4,status:'DONE',startedOn:'2026-01-01'},
  ];
  for(const stop of cases) expect(screenRequiresReason(stop)).toBe(requiresReason(stop));
  expect(requiresReason(cases[0])).toBe(false);
  expect(requiresReason(cases[1])).toBe(true);
  expect(requiresReason(cases[2])).toBe(true);
  expect(requiresReason(cases[3])).toBe(false);
});
